/*
 * Design tokens taken from the Figma file.
 * Every colour, font size and timing used by the components comes from here,
 * so the whole page can be re-themed in one place.
 */
:root {
  /* Colours */
  --color-black: #101011;
  --color-ink: #1e1e1e;
  --color-white: #ffffff;
  --color-yellow: #f2bf25;
  --color-grey-hover: #4a4a4a; /* tile button hover (Figma comment 05) */
  --color-border: #e7e7e7;
  --color-tile-blue: #72a3f3;
  --color-tile-cream: #fdf8eb;
  --color-tile-stone: #e8e4df;
  --color-overlay-soft: rgba(16, 16, 17, 0.2); /* hero arrows */
  --color-overlay: rgba(16, 16, 17, 0.4); /* rating badge */
  --color-progress-track: rgba(231, 231, 231, 0.5);

  /* Typography (Red Hat Display, weights 500 and 700) */
  --font-family: 'Red Hat Display Variable', 'Red Hat Display', system-ui, sans-serif;
  --fw-medium: 500;
  --fw-bold: 700;
  --fs-12: 0.75rem;
  --fs-13: 0.8125rem;
  --fs-14: 0.875rem;
  --fs-16: 1rem;
  --fs-21: 1.3125rem;
  --fs-32: clamp(1.5rem, 1.1rem + 1.2vw, 2rem);
  --fs-56: clamp(2.25rem, 1.4rem + 2.6vw, 3.5rem);

  /* Layout */
  --container-max: 1600px;
  --gutter: clamp(16px, 3vw, 48px);
  --radius-tile: 24px;
  --radius-pill: 100px;

  /* Motion (Figma comment 01: one easing everywhere, ease-out for zooms) */
  --ease-in-out: cubic-bezier(0.4, 0, 0.2, 1);
  --ease-out: cubic-bezier(0, 0, 0.2, 1);
  --duration-hover: 250ms;
  --duration-button: 200ms;
  --duration-fade: 600ms;
  --duration-zoom: 500ms;
  --duration-large: 800ms;

  --header-height: 80px;
}

/* Minimal reset + shared building blocks (container, buttons, icons). */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: var(--font-family);
  font-weight: var(--fw-medium);
  color: var(--color-ink);
  background: var(--color-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body.is-locked {
  overflow: hidden;
}

img {
  display: block;
  max-width: 100%;
}

h1,
h2,
h3,
p,
ul {
  margin: 0;
}

ul {
  padding: 0;
  list-style: none;
}

a {
  color: inherit;
  text-decoration: none;
}

button,
input {
  font: inherit;
  color: inherit;
}

button {
  padding: 0;
  border: 0;
  background: none;
  cursor: pointer;
}

:focus-visible {
  outline: 2px solid var(--color-yellow);
  outline-offset: 3px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* Centered 1600px content column used by every section. */
.container {
  width: 100%;
  max-width: calc(var(--container-max) + 2 * var(--gutter));
  margin-inline: auto;
  padding-inline: var(--gutter);
}

/* Pill button: yellow (hero, shader) and black (tiles) variants. */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 16px 24px;
  border-radius: var(--radius-pill);
  font-size: var(--fs-16);
  font-weight: var(--fw-bold);
  line-height: 1.2;
  white-space: nowrap;
  transition: background-color var(--duration-button) var(--ease-in-out),
    transform var(--duration-button) var(--ease-in-out);
}

.btn:active {
  transform: scale(0.97);
}

.btn--yellow {
  background: var(--color-yellow);
  color: var(--color-ink);
}

.btn--yellow:hover {
  background: #ffd34d;
}

.btn--dark {
  background: var(--color-black);
  color: var(--color-white);
}

.btn--dark:hover {
  background: var(--color-grey-hover);
}

/* Round 48px icon button (hero arrows, header icons, socials). */
.circle-btn {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: var(--radius-pill);
  transition: background-color var(--duration-hover) var(--ease-in-out),
    transform var(--duration-button) var(--ease-in-out);
}

.circle-btn:active {
  transform: scale(0.94);
}

/*
 * Single-colour SVG icon drawn with CSS mask, so it takes `currentColor`.
 * This lets the header switch icons from white to black on hover
 * without editing or duplicating the exported SVG files.
 */
.icon {
  display: inline-block;
  flex-shrink: 0;
  width: var(--icon-w);
  height: var(--icon-h);
  background-color: currentColor;
  -webkit-mask: var(--icon) center / contain no-repeat;
  mask: var(--icon) center / contain no-repeat;
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

import type { CSSProperties } from 'react'

type IconProps = {
  /** URL of an exported single-colour SVG. */
  src: string
  /** Square size in px; use width/height for non-square icons. */
  size?: number
  width?: number
  height?: number
  className?: string
}

/**
 * Renders an SVG as a CSS mask filled with `currentColor` (see `.icon` in base.css).
 * Decorative by default: the surrounding button/link provides the accessible name.
 */
export function Icon({ src, size = 24, width, height, className = '' }: IconProps) {
  const style = {
    '--icon': `url("${src}")`,
    '--icon-w': `${width ?? size}px`,
    '--icon-h': `${height ?? size}px`,
  } as CSSProperties

  return <span className={`icon ${className}`} style={style} aria-hidden="true" />
}

import { useEffect, useRef, useState } from 'react'
import { Icon } from '../Icon/Icon'
import { navItems } from '../../data/navigation'
import { MobileMenu } from './MobileMenu'
import logo from '../../assets/brand/logo-sollux-white.svg'
import angleDown from '../../assets/icons/angle-down.svg'
import searchIcon from '../../assets/icons/search.svg'
import cubeIcon from '../../assets/icons/cube.svg'
import userIcon from '../../assets/icons/user.svg'
import basketIcon from '../../assets/icons/basket.svg'
import './Header.css'

/**
 * Fixed site header.
 * - Transparent over the hero, white on hover/focus (Figma comment 02, 250 ms).
 * - Also turns white once the page is scrolled, so it stays readable on white sections.
 * - Desktop: links with dropdowns. Below 1280px: burger + slide-in menu.
 */
export function Header() {
  const [isScrolled, setIsScrolled] = useState(false)
  const [openSubmenu, setOpenSubmenu] = useState<string | null>(null)
  const [isMenuOpen, setIsMenuOpen] = useState(false)
  const [isSearchOpen, setIsSearchOpen] = useState(false)
  const navRef = useRef<HTMLUListElement>(null)
  const searchInputRef = useRef<HTMLInputElement>(null)

  useEffect(() => {
    const onScroll = () => setIsScrolled(window.scrollY > 8)
    onScroll()
    window.addEventListener('scroll', onScroll, { passive: true })
    return () => window.removeEventListener('scroll', onScroll)
  }, [])

  // Close an open dropdown on outside click or Escape.
  useEffect(() => {
    if (!openSubmenu) return
    const onPointerDown = (event: PointerEvent) => {
      if (!navRef.current?.contains(event.target as Node)) setOpenSubmenu(null)
    }
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpenSubmenu(null)
    }
    document.addEventListener('pointerdown', onPointerDown)
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.removeEventListener('pointerdown', onPointerDown)
      document.removeEventListener('keydown', onKeyDown)
    }
  }, [openSubmenu])

  useEffect(() => {
    if (isSearchOpen) searchInputRef.current?.focus()
  }, [isSearchOpen])

  const isSolid = isScrolled || isMenuOpen || isSearchOpen || openSubmenu !== null

  return (
    <header className={`header ${isSolid ? 'header--solid' : ''}`}>
      <div className="header__inner container">
        <a className="header__logo" href="#top" aria-label="SOLLUX – strona główna">
          <Icon src={logo} width={150} height={48} />
        </a>

        <nav className="header__nav" aria-label="Główna nawigacja">
          <ul className="header__links" ref={navRef}>
            {navItems.map((item) =>
              item.submenu ? (
                <li
                  key={item.label}
                  className={`header__item ${openSubmenu === item.label ? 'is-open' : ''}`}
                  onMouseEnter={() => setOpenSubmenu(item.label)}
                  onMouseLeave={() => setOpenSubmenu(null)}
                >
                  <button
                    type="button"
                    className="header__link"
                    aria-expanded={openSubmenu === item.label}
                    onClick={() =>
                      setOpenSubmenu((current) => (current === item.label ? null : item.label))
                    }
                  >
                    {item.label}
                    <Icon src={angleDown} size={16} className="header__chevron" />
                  </button>
                  <ul className="header__dropdown">
                    {item.submenu.map((sub) => (
                      <li key={sub.label}>
                        <a href={sub.href} onClick={() => setOpenSubmenu(null)}>
                          {sub.swatch && (
                            <span className="header__swatch" style={{ background: sub.swatch }} />
                          )}
                          {sub.label}
                        </a>
                      </li>
                    ))}
                  </ul>
                </li>
              ) : (
                <li key={item.label} className="header__item">
                  <a className="header__link" href={item.href}>
                    {item.label}
                  </a>
                </li>
              ),
            )}
          </ul>
        </nav>

        <form
          className={`header__search ${isSearchOpen ? 'is-open' : ''}`}
          role="search"
          action="#"
          onSubmit={(event) => event.preventDefault()}
        >
          <label className="visually-hidden" htmlFor="site-search">
            Czego szukasz?
          </label>
          <input
            ref={searchInputRef}
            id="site-search"
            type="search"
            name="q"
            placeholder="Czego szukasz?"
            autoComplete="off"
          />
          <button type="submit" className="header__search-submit" aria-label="Szukaj">
            <Icon src={searchIcon} size={20} />
          </button>
        </form>

        <div className="header__actions">
          <a className="header__configurator" href="#konfigurator">
            <Icon src={cubeIcon} size={20} />
            <span>Stwórz swoją lampę</span>
          </a>
          <button
            type="button"
            className="circle-btn header__icon-btn header__search-toggle"
            aria-label={isSearchOpen ? 'Zamknij wyszukiwarkę' : 'Otwórz wyszukiwarkę'}
            aria-expanded={isSearchOpen}
            onClick={() => setIsSearchOpen((open) => !open)}
          >
            <Icon src={searchIcon} size={20} />
          </button>
          <a className="circle-btn header__icon-btn" href="#konto" aria-label="Moje konto">
            <Icon src={userIcon} />
          </a>
          <a className="circle-btn header__icon-btn" href="#koszyk" aria-label="Koszyk">
            <Icon src={basketIcon} width={22} height={19} />
          </a>
          <button
            type="button"
            className="circle-btn header__icon-btn header__burger"
            aria-label="Otwórz menu"
            aria-expanded={isMenuOpen}
            aria-controls="mobile-menu"
            onClick={() => setIsMenuOpen(true)}
          >
            <span className="header__burger-lines" aria-hidden="true" />
          </button>
        </div>
      </div>

      <MobileMenu isOpen={isMenuOpen} onClose={() => setIsMenuOpen(false)} />
    </header>
  )
}

import { useEffect, useRef, useState } from 'react'
import { Icon } from '../Icon/Icon'
import { navItems } from '../../data/navigation'
import angleDown from '../../assets/icons/angle-down.svg'
import cubeIcon from '../../assets/icons/cube.svg'

type MobileMenuProps = {
  isOpen: boolean
  onClose: () => void
}

/**
 * Slide-in navigation for tablet and mobile.
 * Locks page scroll while open, closes on Escape, backdrop click or link click,
 * and moves focus into the panel so keyboard users land in the menu.
 */
export function MobileMenu({ isOpen, onClose }: MobileMenuProps) {
  const [expanded, setExpanded] = useState<string | null>(null)
  const closeButtonRef = useRef<HTMLButtonElement>(null)

  useEffect(() => {
    if (!isOpen) return
    document.body.classList.add('is-locked')
    closeButtonRef.current?.focus()
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose()
    }
    document.addEventListener('keydown', onKeyDown)
    return () => {
      document.body.classList.remove('is-locked')
      document.removeEventListener('keydown', onKeyDown)
    }
  }, [isOpen, onClose])

  return (
    <div className={`mobile-menu ${isOpen ? 'is-open' : ''}`} inert={!isOpen}>
      <div className="mobile-menu__backdrop" onClick={onClose} />
      <div
        id="mobile-menu"
        className="mobile-menu__panel"
        role="dialog"
        aria-modal="true"
        aria-label="Menu"
      >
        <button
          ref={closeButtonRef}
          type="button"
          className="circle-btn mobile-menu__close"
          aria-label="Zamknij menu"
          onClick={onClose}
        >
          <span aria-hidden="true">×</span>
        </button>

        <ul className="mobile-menu__list">
          {navItems.map((item) => (
            <li key={item.label}>
              {item.submenu ? (
                <>
                  <button
                    type="button"
                    className="mobile-menu__link"
                    aria-expanded={expanded === item.label}
                    onClick={() => setExpanded((cur) => (cur === item.label ? null : item.label))}
                  >
                    {item.label}
                    <Icon src={angleDown} size={20} className="mobile-menu__chevron" />
                  </button>
                  <ul className="mobile-menu__sub" hidden={expanded !== item.label}>
                    {item.submenu.map((sub) => (
                      <li key={sub.label}>
                        <a href={sub.href} onClick={onClose}>
                          {sub.label}
                        </a>
                      </li>
                    ))}
                  </ul>
                </>
              ) : (
                <a className="mobile-menu__link" href={item.href} onClick={onClose}>
                  {item.label}
                </a>
              )}
            </li>
          ))}
        </ul>

        <a className="btn btn--dark mobile-menu__cta" href="#konfigurator" onClick={onClose}>
          <Icon src={cubeIcon} size={20} />
          Stwórz swoją lampę
        </a>
      </div>
    </div>
  )
}

/* ---------- Header shell ---------- */
.header {
  position: fixed;
  inset: 0 0 auto;
  z-index: 50;
  color: var(--color-white);
  background-color: rgba(255, 255, 255, 0);
  /* Figma comment 02: background + colours change together, 250 ms ease-in-out. */
  transition: background-color var(--duration-hover) var(--ease-in-out),
    color var(--duration-hover) var(--ease-in-out),
    box-shadow var(--duration-hover) var(--ease-in-out);
}

.header:hover,
.header:focus-within,
.header--solid {
  color: var(--color-black);
  background-color: var(--color-white);
  box-shadow: 0 1px 0 rgba(16, 16, 17, 0.06);
}

.header__inner {
  display: flex;
  align-items: center;
  gap: 64px;
  height: var(--header-height);
}

.header__logo {
  display: flex;
  flex-shrink: 0;
}

/* ---------- Desktop links ---------- */
.header__links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.header__item {
  position: relative;
}

.header__link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: var(--fs-14);
  font-weight: var(--fw-bold);
  line-height: 1.2;
  white-space: nowrap;
  padding-block: 8px;
}

.header__link:hover {
  opacity: 0.7;
}

.header__chevron {
  transition: transform var(--duration-hover) var(--ease-in-out);
}

.header__item.is-open .header__chevron {
  transform: rotate(180deg);
}

/* Dropdown panel: animated with opacity + transform only. */
.header__dropdown {
  position: absolute;
  top: calc(100% + 16px);
  left: -16px;
  min-width: 220px;
  padding: 12px;
  border-radius: 16px;
  background: var(--color-white);
  box-shadow: 0 16px 40px rgba(16, 16, 17, 0.12);
  color: var(--color-ink);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-6px);
  transition: opacity var(--duration-hover) var(--ease-in-out),
    transform var(--duration-hover) var(--ease-in-out),
    visibility 0s linear var(--duration-hover);
}

/* Invisible bridge so the pointer can travel from the link to the panel. */
.header__dropdown::before {
  content: '';
  position: absolute;
  inset: -20px 0 100%;
}

.header__item.is-open .header__dropdown {
  opacity: 1;
  visibility: visible;
  transform: none;
  transition-delay: 0s;
}

.header__dropdown a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 10px;
  font-size: var(--fs-14);
  font-weight: var(--fw-medium);
  transition: background-color var(--duration-button) var(--ease-in-out);
}

.header__dropdown a:hover,
.header__dropdown a:focus-visible {
  background: #f4f4f4;
}

.header__swatch {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgba(16, 16, 17, 0.1);
}

/* ---------- Search ---------- */
.header__search {
  display: flex;
  flex: 1 1 0;
  align-items: center;
  gap: 16px;
  min-width: 0;
  padding: 0 24px;
  height: 50px;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
}

.header__search input {
  flex: 1;
  min-width: 0;
  height: 100%;
  border: 0;
  background: none;
  outline: none;
  font-size: var(--fs-14);
  font-weight: var(--fw-bold);
  line-height: 1.2;
}

.header__search input::placeholder {
  color: currentColor;
  opacity: 1;
}

.header__search input::-webkit-search-cancel-button {
  filter: invert(1);
}

.header--solid .header__search input::-webkit-search-cancel-button,
.header:hover .header__search input::-webkit-search-cancel-button {
  filter: none;
}

.header__search:focus-within {
  border-color: currentColor;
}

.header__search-submit {
  display: flex;
}

/* ---------- Right-hand actions ---------- */
.header__actions {
  display: flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}

.header__configurator {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 11px 16px;
  border-radius: var(--radius-pill);
  font-size: var(--fs-13);
  font-weight: var(--fw-bold);
  line-height: 1.1;
  white-space: nowrap;
