  :root {
    --header-height: 64px;
  }

  .header__logo .icon {
    width: 112px;
    height: 36px;
  }

  .header__inner {
    justify-content: space-between;
    gap: 8px;
  }

  .header__actions {
    gap: 0;
  }

  .header__search-toggle {
    display: inline-flex;
  }

  /* On phones the search field drops below the bar when toggled. */
  .header__search {
    position: absolute;
    top: var(--header-height);
    left: var(--gutter);
    right: var(--gutter);
    background: var(--color-white);
    color: var(--color-black);
    opacity: 0;
    visibility: hidden;
    transform: translateY(-8px);
    transition: opacity var(--duration-hover) var(--ease-in-out),
      transform var(--duration-hover) var(--ease-in-out),
      visibility 0s linear var(--duration-hover);
