import { useEffect, useState } from 'react'

const QUERY = '(prefers-reduced-motion: reduce)'

/** True when the user asked the OS for less motion. Used to stop autoplay and shader. */
export function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(() => window.matchMedia(QUERY).matches)

  useEffect(() => {
    const media = window.matchMedia(QUERY)
    const onChange = () => setReduced(media.matches)
    media.addEventListener('change', onChange)
    return () => media.removeEventListener('change', onChange)
  }, [])

  return reduced
}

import { useEffect, useState, type RefObject } from 'react'

/**
 * True while the element is (at least partly) on screen.
 * Lets the slider and the WebGL shader pause when nobody can see them.
 */
export function useInView(ref: RefObject<Element | null>, rootMargin = '0px') {
  const [inView, setInView] = useState(true)

  useEffect(() => {
    const element = ref.current
    if (!element) return
    const observer = new IntersectionObserver(([entry]) => setInView(entry.isIntersecting), {
      rootMargin,
    })
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref, rootMargin])

  return inView
}

import { useEffect, useState } from 'react'

/** False while the browser tab is in the background. */
export function usePageVisible() {
  const [visible, setVisible] = useState(() => document.visibilityState === 'visible')

  useEffect(() => {
    const onChange = () => setVisible(document.visibilityState === 'visible')
    document.addEventListener('visibilitychange', onChange)
    return () => document.removeEventListener('visibilitychange', onChange)
  }, [])

  return visible
}

import { useEffect, useRef, useState, type CSSProperties } from 'react'
import backdrop from '../../assets/hero/slide-1-backdrop.jpg'
import rock from '../../assets/hero/rock.png'
import lampBeige from '../../assets/hero/lamp-beige.png'
import lampOlive from '../../assets/hero/lamp-olive.png'
import lampTerracotta from '../../assets/hero/lamp-terracotta.png'

/**
 * Slide 1 of the hero, rebuilt from layers so the lamps can move (Figma comment 03).
 *
 * Every layer is positioned on a 1920×1080 "stage" (the Figma frame size) using
 * percentages, so the composition is identical to the flat design at rest.
 * - Pointer movement shifts each layer by a different amount (parallax depth).
 * - Clicking a lamp switches it on: a warm glow fades in from its diffuser.
 */

type Lamp = {
  id: string
  label: string
  src: string
  /** Box on the 1920×1080 stage, in px. */
  x: number
  y: number
  width: number
  height: number
  /** Centre of the light diffuser, as a fraction of the lamp image. */
  faceX: number
  faceY: number
  /** How strongly the lamp follows the pointer. */
  depth: number
}

const STAGE_W = 1920
const STAGE_H = 1080

const lamps: Lamp[] = [
  { id: 'terracotta', label: 'terakotowa', src: lampTerracotta, x: 435, y: 440, width: 398, height: 377, faceX: 0.6, faceY: 0.67, depth: 26 },
  { id: 'beige', label: 'beżowa', src: lampBeige, x: 772, y: 113, width: 356, height: 368, faceX: 0.6, faceY: 0.64, depth: 16 },
  { id: 'olive', label: 'oliwkowa', src: lampOlive, x: 1083, y: 337, width: 437, height: 412, faceX: 0.19, faceY: 0.83, depth: 34 },
]

const ROCK = { x: 296, y: 791, width: 1360, height: 289, depth: -8 }

/** Converts stage pixels to percentages of the stage. */
const box = (x: number, y: number, width: number, height: number): CSSProperties => ({
  left: `${(x / STAGE_W) * 100}%`,
  top: `${(y / STAGE_H) * 100}%`,
  width: `${(width / STAGE_W) * 100}%`,
  height: `${(height / STAGE_H) * 100}%`,
})

type LampSceneProps = {
  /** Parallax only runs while the slide is visible. */
  isActive: boolean
}

export function LampScene({ isActive }: LampSceneProps) {
  const stageRef = useRef<HTMLDivElement>(null)
  const [litLamps, setLitLamps] = useState<Record<string, boolean>>({})

  // Pointer parallax: ease the current position towards the pointer every frame,
  // and expose it as CSS variables (--px, --py in the range -1..1).
  useEffect(() => {
    const stage = stageRef.current
    const hero = stage?.closest('section')
    if (!stage || !hero || !isActive) return

    const target = { x: 0, y: 0 }
    const current = { x: 0, y: 0 }
    let frame = 0

    const onPointerMove = (event: PointerEvent) => {
      if (event.pointerType === 'touch') return
      const rect = hero.getBoundingClientRect()
      target.x = ((event.clientX - rect.left) / rect.width) * 2 - 1
      target.y = ((event.clientY - rect.top) / rect.height) * 2 - 1
    }
    const onPointerLeave = () => {
      target.x = 0
      target.y = 0
    }
    const tick = () => {
      current.x += (target.x - current.x) * 0.06
      current.y += (target.y - current.y) * 0.06
      stage.style.setProperty('--px', current.x.toFixed(4))
      stage.style.setProperty('--py', current.y.toFixed(4))
      frame = requestAnimationFrame(tick)
    }

    hero.addEventListener('pointermove', onPointerMove)
    hero.addEventListener('pointerleave', onPointerLeave)
    frame = requestAnimationFrame(tick)
    return () => {
      hero.removeEventListener('pointermove', onPointerMove)
      hero.removeEventListener('pointerleave', onPointerLeave)
      cancelAnimationFrame(frame)
    }
  }, [isActive])

  const toggleLamp = (id: string) => setLitLamps((lit) => ({ ...lit, [id]: !lit[id] }))
  const litCount = Object.values(litLamps).filter(Boolean).length

  return (
    <div className="lamp-scene" ref={stageRef}>
      <img className="lamp-scene__backdrop" src={backdrop} alt="" />

      {/* Warm ambient wash that grows with the number of lamps switched on. */}
      <div className="lamp-scene__ambient" style={{ opacity: litCount / lamps.length }} />

      <div
        className="lamp-scene__layer"
        style={{ ...box(ROCK.x, ROCK.y, ROCK.width, ROCK.height), '--depth': ROCK.depth } as CSSProperties}
      >
        <img src={rock} alt="" />
      </div>

      {lamps.map((lamp, index) => {
        const isOn = Boolean(litLamps[lamp.id])
        return (
          <div
            key={lamp.id}
            className={`lamp-scene__layer lamp ${isOn ? 'is-on' : ''}`}
            style={
              {
                ...box(lamp.x, lamp.y, lamp.width, lamp.height),
                '--depth': lamp.depth,
                '--face-x': `${lamp.faceX * 100}%`,
                '--face-y': `${lamp.faceY * 100}%`,
                '--float-delay': `${index * -2.1}s`,
              } as CSSProperties
            }
          >
            <span className="lamp__glow" aria-hidden="true" />
            <button
              type="button"
              className="lamp__button"
              aria-pressed={isOn}
              aria-label={`${isOn ? 'Wyłącz' : 'Włącz'} lampę ${lamp.label}`}
              title={isOn ? 'Kliknij, aby wyłączyć' : 'Kliknij, aby włączyć'}
              onClick={() => toggleLamp(lamp.id)}
            >
              <img src={lamp.src} alt="" draggable={false} />
              <span className="lamp__bulb" aria-hidden="true" />
            </button>
          </div>
        )
      })}
    </div>
  )
}

import { useCallback, useRef, useState } from 'react'
import { LampScene } from './LampScene'
import { useInView } from '../../hooks/useInView'
import { usePageVisible } from '../../hooks/usePageVisible'
import { usePrefersReducedMotion } from '../../hooks/usePrefersReducedMotion'
import interior from '../../assets/hero/slide-2-interior.jpg'
import arrowLeft from '../../assets/icons/arrow-left.svg'
import arrowRight from '../../assets/icons/arrow-right.svg'
import star from '../../assets/icons/star.svg'
import './Hero.css'

/** Autoplay delay from Figma comment 04. Also drives the progress bar fill. */
const SLIDE_DURATION_MS = 3000

const slides = [
  { id: 'lamps', label: 'Lampy SOLLUX na tle zachodu słońca' },
  { id: 'interior', label: 'Przedpokój z lampami SOLLUX' },
]

/**
 * Hero slider (Figma comment 04):
 * - autoplay every 3 s, 600 ms crossfade, image settles from scale 1.05 to 1;
 * - the yellow progress bar fills linearly over 3 s and the end of that CSS
 *   animation is what advances the slide, so bar and slide never drift apart;
 * - pauses when the tab is hidden, the hero is off-screen, or reduced motion is on.
 */
export function Hero() {
  const [activeIndex, setActiveIndex] = useState(0)
  const heroRef = useRef<HTMLElement>(null)
  const inView = useInView(heroRef)
  const pageVisible = usePageVisible()
  const reducedMotion = usePrefersReducedMotion()

  const isPlaying = inView && pageVisible && !reducedMotion

  const goTo = useCallback((index: number) => {
    setActiveIndex((index + slides.length) % slides.length)
  }, [])

  return (
    <section
      className="hero"
      id="top"
      ref={heroRef}
      aria-roledescription="karuzela"
      aria-label="Bestsellery SOLLUX"
    >
      <div className="hero__slides">
        {slides.map((slide, index) => (
          <div
            key={slide.id}
            className={`hero__slide ${index === activeIndex ? 'is-active' : ''}`}
            role="group"
            aria-roledescription="slajd"
            aria-label={`${index + 1} z ${slides.length}: ${slide.label}`}
            aria-hidden={index !== activeIndex}
            inert={index !== activeIndex}
          >
            <div className="hero__media">
              {slide.id === 'lamps' ? (
                <LampScene isActive={index === activeIndex} />
              ) : (
                <img className="hero__image" src={interior} alt="" />
              )}
            </div>
          </div>
        ))}
      </div>

      <div className="hero__content container">
        <div className="hero__copy">
          <p className="hero__eyebrow">Bestsellery SOLLUX</p>
          <h1 className="hero__title">
            Kolor i forma
            <br />
            w nowym świetle
          </h1>
        </div>
        <a className="btn btn--yellow hero__cta" href="#bestsellery">
          Sprawdź bestsellery
        </a>
      </div>

      <button
        type="button"
        className="circle-btn hero__arrow hero__arrow--prev"
        aria-label="Poprzedni slajd"
        onClick={() => goTo(activeIndex - 1)}
      >
        <img src={arrowLeft} alt="" width={24} height={24} />
      </button>
      <button
        type="button"
        className="circle-btn hero__arrow hero__arrow--next"
        aria-label="Następny slajd"
        onClick={() => goTo(activeIndex + 1)}
      >
        <img src={arrowRight} alt="" width={24} height={24} />
      </button>

      <div className="hero__progress">
        {slides.map((slide, index) => (
          <button
            key={slide.id}
            type="button"
            className={`hero__progress-step ${index === activeIndex ? 'is-active' : ''}`}
            aria-label={`Pokaż slajd ${index + 1}`}
            aria-current={index === activeIndex}
            onClick={() => goTo(index)}
          >
            {index === activeIndex && (
              <span
                // A new key restarts the fill animation whenever the slide changes.
                key={`fill-${activeIndex}`}
                className={`hero__progress-fill ${isPlaying ? '' : 'is-paused'} ${
                  reducedMotion ? 'is-static' : ''
                }`}
                style={{ animationDuration: `${SLIDE_DURATION_MS}ms` }}
                onAnimationEnd={() => goTo(activeIndex + 1)}
              />
            )}
          </button>
        ))}
      </div>

      <a className="hero__rating" href="#opinie" aria-label="Ocena 4.8 – uwielbiany przez klientów">
        <span className="hero__rating-score">
          4.8
          <img src={star} alt="" width={14} height={17} />
        </span>
        <span className="hero__rating-text">Uwielbiany przez klientów</span>
      </a>
    </section>
  )
}

/* ---------- Hero frame ---------- */
.hero {
  position: relative;
  display: flex;
  align-items: center;
  /* Figma frame is 1920×1080; keep it a full screen but never taller than the design. */
  height: clamp(560px, 100svh, 1080px);
  overflow: hidden;
  /* The lamp stage sizes itself from the hero's box (container query units). */
  container-type: size;
  background: #b3774c;
  color: var(--color-white);
}

.hero__slides,
.hero__slide,
.hero__media {
  position: absolute;
  inset: 0;
}

/* Crossfade: 600 ms ease-in-out (Figma comment 04). */
.hero__slide {
  opacity: 0;
  transition: opacity var(--duration-fade) var(--ease-in-out);
}

.hero__slide.is-active {
  opacity: 1;
}

/* Image settles from 1.05 to 1 while it fades in (800 ms ease-out). */
.hero__media {
  transform: scale(1.05);
  transition: transform 0s linear var(--duration-fade);
}

.hero__slide.is-active .hero__media {
  transform: scale(1);
  transition: transform var(--duration-large) var(--ease-out);
}

.hero__image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* ---------- Copy ---------- */
.hero__content {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 32px;
  padding-block: 64px;
  /* Let clicks reach the lamps behind the text; the button opts back in. */
  pointer-events: none;
}

.hero__copy {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.hero__eyebrow {
  font-size: var(--fs-16);
  font-weight: var(--fw-medium);
  line-height: 1.2;
}

.hero__title {
  font-size: var(--fs-56);
  font-weight: var(--fw-bold);
  line-height: 1;
}

.hero__cta {
  pointer-events: auto;
}

/* ---------- Arrows ---------- */
.hero__arrow {
  position: absolute;
  top: 50%;
  z-index: 3;
  background: var(--color-overlay-soft);
  transform: translateY(-50%);
}

.hero__arrow:hover {
  background: var(--color-overlay);
}

.hero__arrow:active {
  transform: translateY(-50%) scale(0.94);
}

.hero__arrow--prev {
  left: 72px;
}

.hero__arrow--next {
  right: 72px;
}

/* ---------- Progress bar ---------- */
.hero__progress {
  position: absolute;
  bottom: 22px;
  left: 50%;
  z-index: 3;
  display: flex;
  gap: 4px;
  transform: translateX(-50%);
}

/* 64×2 px bar from Figma, with a taller invisible hit area. */
.hero__progress-step {
  position: relative;
  width: 64px;
  height: 22px;
}

.hero__progress-step::before,
.hero__progress-fill {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 10px;
  height: 2px;
}

.hero__progress-step::before {
  background: var(--color-progress-track);
}

.hero__progress-fill {
  background: var(--color-yellow);
  transform-origin: left center;
  animation-name: hero-progress;
  animation-timing-function: linear;
  animation-fill-mode: forwards;
}

.hero__progress-fill.is-paused {
  animation-play-state: paused;
}

.hero__progress-fill.is-static {
  animation: none !important;
}

@keyframes hero-progress {
  from {
    transform: scaleX(0);
  }

  to {
    transform: scaleX(1);
  }
}

/* ---------- Rating badge ---------- */
.hero__rating {
  position: absolute;
  right: 72px;
  bottom: 32px;
  z-index: 3;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 24px;
  border-radius: var(--radius-pill);
  background: var(--color-overlay);
  transition: background-color var(--duration-hover) var(--ease-in-out);
}

.hero__rating:hover {
  background: rgba(16, 16, 17, 0.6);
}

.hero__rating-score {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: var(--fs-21);
  font-weight: var(--fw-bold);
  line-height: 1.1;
}

.hero__rating-text {
  font-size: var(--fs-13);
  font-weight: var(--fw-medium);
  line-height: 1.1;
}

/* ---------- Lamp scene (slide 1) ---------- */

/*
 * A 16:9 stage that always covers the hero (like object-fit: cover).
 * 100cqw / 100cqh are the hero's width / height.
 */
.lamp-scene {
  --px: 0;
  --py: 0;
  position: absolute;
  top: 50%;
  left: 50%;
  width: max(100cqw, 100cqh * 16 / 9);
  aspect-ratio: 16 / 9;
  transform: translate(-50%, -50%);
}

.lamp-scene__backdrop {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.lamp-scene__ambient {
  position: absolute;
  inset: 0;
  background: radial-gradient(60% 70% at 52% 55%, rgba(255, 196, 120, 0.35), transparent 70%);
  mix-blend-mode: soft-light;
  pointer-events: none;
  transition: opacity var(--duration-large) var(--ease-out);
}

.lamp-scene__layer {
  position: absolute;
  /* Parallax: each layer moves by its own depth (px on the 1920 stage). */
  transform: translate3d(
    calc(var(--px) * var(--depth) * 1px),
    calc(var(--py) * var(--depth) * 0.6px),
    0
  );
  will-change: transform;
}

.lamp-scene__layer > img,
.lamp__button img {
  width: 100%;
  height: 100%;
  user-select: none;
}

/* Gentle idle float, on an inner element so it combines with the parallax. */
.lamp__button {
  position: relative;
  display: block;
  width: 100%;
  height: 100%;
  border-radius: 40%;
  animation: lamp-float 7s var(--ease-in-out) var(--float-delay) infinite alternate;
  -webkit-tap-highlight-color: transparent;
}

.lamp__button:focus-visible {
  outline-offset: -12px;
}

.lamp__button img {
  transition: transform var(--duration-zoom) var(--ease-out);
}

.lamp__button:hover img {
  transform: scale(1.03) rotate(-1deg);
}

.lamp__button:active img {
  transform: scale(0.98);
}

@keyframes lamp-float {
  from {
    transform: translateY(-1.2%) rotate(-1.2deg);
  }

  to {
    transform: translateY(1.2%) rotate(1.2deg);
  }
}

/* Light: a bright disc on the diffuser + a large warm halo, both opacity-only. */
.lamp__bulb,
.lamp__glow {
  position: absolute;
  left: var(--face-x);
  top: var(--face-y);
  border-radius: 50%;
  pointer-events: none;
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.85);
  transition: opacity var(--duration-zoom) var(--ease-out),
    transform var(--duration-large) var(--ease-out);
}

.lamp__bulb {
  width: 46%;
  aspect-ratio: 1;
  background: radial-gradient(circle, #fffaf0 0%, #ffe7b8 38%, rgba(255, 214, 150, 0) 70%);
  mix-blend-mode: screen;
}

.lamp__glow {
  width: 260%;
  aspect-ratio: 1;
  background: radial-gradient(
    circle,
    rgba(255, 230, 170, 0.75) 0%,
    rgba(255, 196, 110, 0.35) 22%,
    rgba(255, 170, 90, 0) 60%
  );
  mix-blend-mode: screen;
}

.lamp.is-on .lamp__bulb,
.lamp.is-on .lamp__glow {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1);
}

.lamp.is-on .lamp__glow {
  animation: lamp-flicker 4s var(--ease-in-out) infinite alternate;
}

@keyframes lamp-flicker {
  from {
    opacity: 0.9;
  }

  to {
    opacity: 1;
  }
}

/* ---------- Responsive ---------- */
@media (max-width: 1279px) {
  .hero__arrow--prev {
    left: 24px;
  }

  .hero__arrow--next {
    right: 24px;
  }

  .hero__rating {
    right: 24px;
  }

  .hero__content {
    padding-inline: calc(var(--gutter) + 72px);
  }
}

@media (max-width: 767px) {
  .hero {
    align-items: flex-end;
    height: max(560px, 100svh);
  }

  /* Soft scrim keeps the copy readable over the lamps on small screens. */
  .hero::after {
    content: '';
    position: absolute;
    inset: auto 0 0;
    height: 60%;
    z-index: 1;
    background: linear-gradient(to top, rgba(16, 16, 17, 0.45), transparent);
    pointer-events: none;
  }

  .hero__content {
    padding-inline: var(--gutter);
    padding-block: 0 112px;
    gap: 24px;
  }

  .hero__arrow {
    top: auto;
    bottom: 24px;
    transform: none;
  }

  .hero__arrow:active {
    transform: scale(0.94);
  }

  .hero__arrow--prev {
    left: var(--gutter);
  }

  .hero__arrow--next {
    right: auto;
    left: calc(var(--gutter) + 56px);
  }

  .hero__progress {
    bottom: 37px;
    left: auto;
    right: var(--gutter);
    transform: none;
  }

  .hero__progress-step {
    width: 40px;
  }

  .hero__rating {
    top: calc(var(--header-height) + 16px);
    right: var(--gutter);
    bottom: auto;
    padding: 8px 16px;
  }
}

