import type { ReactNode } from 'react'
import thoroPhoto from '../../assets/tiles/thoro-woman.png'
import laptop from '../../assets/tiles/configurator-laptop.png'
import ipad from '../../assets/tiles/catalog-ipad.png'
import phoneBack from '../../assets/tiles/smart-phone-back.png'
import phoneFront from '../../assets/tiles/smart-phone-front.png'
import './Tiles.css'

type TileArt = {
  src: string
  /** Modifier class that positions this image (see Tiles.css). */
  className: string
}

type Tile = {
  id: string
  eyebrow: string
  title: ReactNode
  cta: string
  href: string
  /** `light` = white text (dark/colour tiles), `dark` = black text. */
  tone: 'light' | 'dark'
  /** `narrow` = 648px column, `wide` = 936px column in the 1600px grid. */
  size: 'narrow' | 'wide'
  art: TileArt[]
}

const rows: Tile[][] = [
  [
    {
      id: 'thoro',
      eyebrow: 'Marka THORO',
      title: 'Poznaj lampy premium',
      cta: 'Odwiedź sklep THORO',
      href: '#thoro',
      tone: 'light',
      size: 'narrow',
      art: [{ src: thoroPhoto, className: 'tile__art--cover' }],
    },
    {
      id: 'configurator',
      eyebrow: 'Konfigurator 3D',
      title: (
        <>
          Wybierz projekt i dostosuj
          <br />
          go do swojego wnętrza
        </>
      ),
      cta: 'Stwórz swój projekt',
      href: '#konfigurator',
      tone: 'light',
      size: 'wide',
      art: [{ src: laptop, className: 'tile__art--laptop' }],
    },
  ],
  [
    {
      id: 'catalog',
      eyebrow: 'Katalog',
      title: 'Odkryj najnowszy katalog',
      cta: 'Sprawdź katalog',
      href: '#katalog',
      tone: 'dark',
      size: 'wide',
      art: [{ src: ipad, className: 'tile__art--ipad' }],
    },
    {
      id: 'smart',
      eyebrow: 'SOLLUX SMART',
      title: 'Przymierz lampę w aplikacji',
      cta: 'Pobierz aplikacje na telefon',
      href: '#sollux-smart',
      tone: 'dark',
      size: 'narrow',
      art: [
        { src: phoneBack, className: 'tile__art--phone-back' },
        { src: phoneFront, className: 'tile__art--phone-front' },
      ],
    },
  ],
]

/**
 * 2×2 promo grid. On hover (Figma comment 05) the artwork zooms to 110 %
 * (500 ms ease-out, clipped by the tile) and the black button turns #4A4A4A.
 * The CTA link is stretched over the whole tile, so the tile is one big link.
 */
export function Tiles() {
  return (
    <div className="tiles">
      {rows.map((row, rowIndex) => (
        <div key={rowIndex} className={`tiles__row tiles__row--${rowIndex + 1}`}>
          {row.map((tile) => (
            <article
              key={tile.id}
              className={`tile tile--${tile.id} tile--${tile.size} tile--${tile.tone}`}
            >
              <div className="tile__media" aria-hidden="true">
                {tile.art.map((art) => (
                  <img
                    key={art.className}
                    className={`tile__art ${art.className}`}
                    src={art.src}
                    alt=""
                    loading="lazy"
                  />
                ))}
              </div>
              <div className="tile__text">
                <div className="tile__heading">
                  <p className="tile__eyebrow">{tile.eyebrow}</p>
                  <h2 className="tile__title">{tile.title}</h2>
                </div>
                <a className="btn btn--dark tile__cta" href={tile.href}>
                  {tile.cta}
                </a>
              </div>
            </article>
          ))}
        </div>
      ))}
    </div>
  )
}

/*
 * Grid: two rows of 16px-gapped tiles. Column widths follow Figma
 * (648 + 936 and 936 + 648 inside 1600px) and every tile keeps the
 * 518px design height through aspect-ratio, so artwork placed in
 * percentages stays exactly where the designer put it.
 */
.tiles {
  display: grid;
  gap: 16px;
}

.tiles__row {
  display: grid;
  gap: 16px;
}

.tiles__row--1 {
  grid-template-columns: 648fr 936fr;
}

.tiles__row--2 {
  grid-template-columns: 936fr 648fr;
}

.tile {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  overflow: hidden;
  border-radius: var(--radius-tile);
  isolation: isolate;
}

.tile--narrow {
  aspect-ratio: 648 / 518;
}

.tile--wide {
  aspect-ratio: 936 / 518;
}

.tile--light {
  color: var(--color-white);
}

.tile--dark {
  color: var(--color-black);
}

.tile--configurator {
  background: var(--color-tile-blue);
}

.tile--catalog {
  background: var(--color-tile-cream);
}

.tile--smart {
  background: var(--color-tile-stone);
}

/* ---------- Artwork ---------- */
.tile__media {
  position: absolute;
  inset: 0;
  z-index: -1;
  /* Zoom origin roughly in the middle of the visual weight. */
  transform-origin: 60% 45%;
  transition: transform var(--duration-zoom) var(--ease-out);
}

.tile:hover .tile__media,
.tile:focus-within .tile__media {
  transform: scale(1.1);
}

.tile__art {
  position: absolute;
  height: auto;
}

.tile__art--cover {
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

/* Positions = Figma x / tile width, y / tile height. */
.tile__art--laptop {
  left: 35.897%;
  top: 0;
  width: 64.103%;
}

.tile__art--ipad {
  left: 45.299%;
  top: 10.425%;
  width: 52.137%;
}

.tile__art--phone-back {
  left: 12.191%;
  top: 13.9%;
  width: 35.494%;
}

.tile__art--phone-front {
  left: 33.951%;
  top: 18.726%;
  width: 64.66%;
}

/* ---------- Copy ---------- */
.tile__text {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 24px;
  padding: 48px;
}

.tile__heading {
  display: flex;
  flex-direction: column;
  gap: 12px;
  font-weight: var(--fw-bold);
  line-height: 1.1;
}

.tile__eyebrow {
  font-size: var(--fs-21);
}

.tile__title {
  font-size: var(--fs-32);
