const { chromium } = require('playwright');
const assert = (c, m) => { console.log((c ? 'PASS ' : 'FAIL ') + m); };
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  const errors = [];
  const page = await browser.newPage({ viewport: { width: 1920, height: 1080 } });
  page.on('pageerror', e => errors.push(e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
  await page.goto('http://127.0.0.1:5173/', { waitUntil: 'networkidle' });
  await page.mouse.move(960, 600);
  const bg = () => page.$eval('.header', el => getComputedStyle(el).backgroundColor);
  await page.waitForTimeout(400);
  assert((await bg()) === 'rgba(0, 0, 0, 0)' || (await bg()).endsWith(', 0)'), 'header transparent over hero: ' + await bg());
  await page.mouse.move(960, 40); await page.waitForTimeout(400);
  assert((await bg()) === 'rgb(255, 255, 255)', 'header white on hover: ' + await bg());
  // dropdown
  await page.hover('.header__item:first-child .header__link'); await page.waitForTimeout(350);
  assert(await page.$eval('.header__item:first-child .header__dropdown', el => getComputedStyle(el).visibility === 'visible'), 'dropdown opens on hover');
  await page.screenshot({ path: 'shots/dropdown.png', clip: { x: 0, y: 0, width: 900, height: 400 } });
  await page.mouse.move(960, 600); await page.waitForTimeout(400);
  // slider autoplay
  const active = () => page.$$eval('.hero__slide', els => els.findIndex(e => e.classList.contains('is-active')));
  const a0 = await active(); await page.waitForTimeout(3400); const a1 = await active();
  assert(a0 === 0 && a1 === 1, `autoplay advanced ${a0} -> ${a1}`);
  await page.click('.hero__arrow--next'); await page.waitForTimeout(100);
  assert((await active()) === 0, 'next arrow wraps to slide 1');
  await page.click('.hero__arrow--prev'); await page.waitForTimeout(100);
  assert((await active()) === 1, 'prev arrow goes to slide 2');
  await page.click('.hero__progress-step:first-child'); await page.waitForTimeout(700);
  assert((await active()) === 0, 'progress step click selects slide 1');
  // lamp toggle
  await page.click('.lamp:nth-of-type(3) .lamp__button', { force: true });
  await page.waitForTimeout(700);
  const pressed = await page.$$eval('.lamp__button', els => els.map(e => e.getAttribute('aria-pressed')));
  assert(pressed.includes('true'), 'lamp turns on after click: ' + pressed);
  await page.mouse.move(1400, 300); await page.waitForTimeout(800);
  const px = await page.$eval('.lamp-scene', el => el.style.getPropertyValue('--px'));
  assert(Math.abs(parseFloat(px)) > 0.1, 'parallax var follows pointer: ' + px);
  await page.screenshot({ path: 'shots/lamp-on.png' });
  // tile hover
  await page.hover('.tile--catalog'); await page.waitForTimeout(700);
  const t = await page.$eval('.tile--catalog .tile__media', el => getComputedStyle(el).transform);
  const b = await page.$eval('.tile--catalog .tile__cta', el => getComputedStyle(el).backgroundColor);
  assert(t.startsWith('matrix(1.1'), 'tile image zooms: ' + t);
  assert(b === 'rgb(74, 74, 74)', 'tile button turns grey: ' + b);
  // scrolled header
  await page.mouse.move(960, 900);
  await page.evaluate(() => window.scrollTo(0, 1500)); await page.waitForTimeout(500);
  assert((await bg()) === 'rgb(255, 255, 255)', 'header white after scroll');
  // mobile
  const m = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true });
  m.on('pageerror', e => errors.push('mobile: ' + e.message));
  await m.goto('http://127.0.0.1:5173/', { waitUntil: 'networkidle' });
  await m.tap('.header__burger'); await m.waitForTimeout(700);
  assert(await m.$eval('.mobile-menu', el => el.classList.contains('is-open')), 'mobile menu opens');
  await m.tap('.mobile-menu__link'); await m.waitForTimeout(300);
  assert(await m.$eval('.mobile-menu__sub', el => !el.hidden), 'mobile submenu expands');
  await m.screenshot({ path: 'shots/m-menu.png' });
  await m.keyboard.press('Escape'); await m.waitForTimeout(700);
  assert(!(await m.$eval('.mobile-menu', el => el.classList.contains('is-open'))), 'Escape closes menu');
  await m.tap('.header__search-toggle'); await m.waitForTimeout(400);
  assert(await m.evaluate(() => document.activeElement?.id === 'site-search'), 'search toggle focuses input');
  await m.screenshot({ path: 'shots/m-search.png' });
  const ox = await m.evaluate(() => document.documentElement.scrollWidth - innerWidth);
  assert(ox === 0, 'no horizontal overflow on mobile: ' + ox);
  console.log('errors:', JSON.stringify(errors));
  await browser.close();
})();

