// Production-build audit: overflow, console errors, failed requests, broken images, bytes.
const { chromium } = require('playwright');
const URL = process.env.URL || 'http://127.0.0.1:4173/';
(async () => {
  const browser = await chromium.launch({ args: ['--use-gl=angle', '--use-angle=swiftshader', '--enable-unsafe-swiftshader'] });
  for (const [w, h, mobile] of [[1920,1080],[1440,900],[1280,800],[1180,820],[1024,768],[820,1180,1],[768,1024,1],[600,900,1],[390,844,1],[360,740,1],[320,640,1]]) {
    const ctx = await browser.newContext({ viewport: { width: w, height: h }, isMobile: !!mobile, hasTouch: !!mobile });
    const page = await ctx.newPage();
    const issues = []; let bytes = 0;
    page.on('console', m => { if (m.type() === 'error' || (m.type() === 'warning' && !/GPU stall|GL Driver/.test(m.text()))) issues.push(m.type() + ': ' + m.text()); });
    page.on('pageerror', e => issues.push('pageerror: ' + e.message));
    page.on('requestfailed', r => issues.push('failed: ' + r.url()));
    page.on('response', async r => { if (r.status() >= 400) issues.push(r.status() + ' ' + r.url()); try { bytes += (await r.body()).length } catch {} });
    await page.goto(URL, { waitUntil: 'load' });
    const firstLoad = bytes;
    await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 400) { scrollTo(0, y); await new Promise(r => setTimeout(r, 80)); } });
    await page.waitForLoadState('networkidle');
    const r = await page.evaluate(() => {
      const vw = document.documentElement.clientWidth;
      const wide = [...document.querySelectorAll('body *')].filter(el => { const b = el.getBoundingClientRect(); const cs = getComputedStyle(el); return b.width > 0 && (b.right > vw + 1 || b.left < -1) && cs.position !== 'fixed' && !el.closest('.hero, .mobile-menu, .value-props__list, [aria-hidden="true"]'); }).map(el => el.className || el.tagName).slice(0, 5);
      const broken = [...document.images].filter(i => i.complete && i.naturalWidth === 0).map(i => i.src);
      const noAlt = [...document.images].filter(i => !i.hasAttribute('alt')).length;
      return { overflowX: document.documentElement.scrollWidth - innerWidth, wide, broken, noAlt, imgs: document.images.length };
    });
    console.log(`${w}px  overflowX=${r.overflowX} outside=${JSON.stringify(r.wide)} broken=${r.broken.length} noAlt=${r.noAlt} imgs=${r.imgs} firstLoad=${(firstLoad/1024).toFixed(0)}KB total=${(bytes/1024).toFixed(0)}KB issues=${JSON.stringify(issues)}`);
    await ctx.close();
  }
  await browser.close();
})();
