            events.append({'role': 'system', 'kind': 'background_notification', 'timestamp': ts,
                           'content': html.unescape(s.group(1)).strip() if s else clean(c)})
        else:
            events.append({'role': 'system', 'kind': 'other', 'timestamp': ts, 'content': clean(c)})
        continue
    for b in c:
        if b.get('type') == 'tool_result':
            parts = b.get('content')
            out = []
            if isinstance(parts, str):
                out.append({'type': 'text', 'text': clean(parts)})
            else:
                for p in parts or []:
                    if p.get('type') == 'text':
