                        if txt: out.append({'type': 'text', 'text': txt})
                    elif p.get('type') == 'image':
                        out.append({'type': 'image', 'note': 'Image returned by the tool (screenshot/render); binary data not included'}); stats['images_omitted'] += 1
                    else:
